def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"[A-Z]+[0-9]*|[0-9]+|<>|<=|>=|[+\-*/(),:=<>]"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }
    errors = {"#DIV/0!", "#CYCLE!"}
    values = {}
    active = set()

    def parse_integer(text):
        negative = text.startswith("-")
        if negative:
            text = text[1:]
        result = 0
        for start in range(0, len(text), 9):
            part = text[start:start + 9]
            result = result * (10 ** len(part)) + int(part)
        return -result if negative else result

    def parse(text):
        tokens = token_pattern.findall(text)
        operands = []
        operators = []
        expecting_operand = True

        def apply_operator():
            op = operators.pop()
            if op == "neg":
                operands.append(("neg", operands.pop()))
            else:
                right = operands.pop()
                left = operands.pop()
                operands.append((op, left, right))

        for i, token in enumerate(tokens):
            if token[0].isdigit():
                operands.append(("number", parse_integer(token)))
                expecting_operand = False
            elif token[0].isalpha():
                if i + 1 < len(tokens) and tokens[i + 1] == "(":
                    operators.append(("function", token))
                    expecting_operand = True
                else:
                    operands.append(("ref", token))
                    expecting_operand = False
            elif token == "(":
                operators.append(["(", 0])
                expecting_operand = True
            elif token == ",":
                while not isinstance(operators[-1], list):
                    apply_operator()
                operators[-1][1] += 1
                expecting_operand = True
            elif token == ")":
                while not isinstance(operators[-1], list):
                    apply_operator()
                _, commas = operators.pop()
                if operators and isinstance(operators[-1], tuple):
                    _, name = operators.pop()
                    count = commas + 1
                    args = operands[-count:]
                    del operands[-count:]
                    operands.append(("call", name, args))
                expecting_operand = False
            else:
                op = "neg" if token == "-" and expecting_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "neg"
                        )
                    )
                ):
                    apply_operator()
                operators.append(op)
                expecting_operand = True

        while operators:
            apply_operator()
        return operands[0]

    def function_arguments(args):
        for arg in args:
            if arg[0] != ":":
                yield arg
                continue

            first = arg[1][1]
            second = arg[2][1]
            left = min(ord(first[0]), ord(second[0]))
            right = max(ord(first[0]), ord(second[0]))
            top = min(int(first[1:]), int(second[1:]))
            bottom = max(int(first[1:]), int(second[1:]))

            for row in range(top, bottom + 1):
                for column in range(left, right + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("ref", name)

    def evaluate(root):
        tasks = [("cell", root)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name not in cells:
                    results.append(0)
                elif name in values:
                    results.append(values[name])
                elif name in active:
                    results.append("#CYCLE!")
                else:
                    active.add(name)
                    content = cells[name]
                    tasks.append(("finish_cell", name))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        results.append(parse_integer(content))

            elif kind == "finish_cell":
                name = task[1]
                values[name] = results[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                op = node[0]

                if op == "number":
                    results.append(node[1])
                elif op == "ref":
                    tasks.append(("cell", node[1]))
                elif op == "neg":
                    tasks.append(("negate",))
                    tasks.append(("eval", node[1]))
                elif op == "call":
                    name, args = node[1], node[2]
                    if name == "IF":
                        tasks.append(("if_condition", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        initial = 0 if name == "SUM" else None
                        tasks.append(
                            ("function_next", name, iter(function_arguments(args)), initial)
                        )
                else:
                    tasks.append(("binary_left", op, node[2]))
                    tasks.append(("eval", node[1]))

            elif kind == "negate":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                elif op == ">=":
                    results.append(left >= right)

            elif kind == "if_condition":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "function_next":
                name, arguments, accumulated = task[1:]
                try:
                    argument = next(arguments)
                except StopIteration:
                    results.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append(("function_value", name, arguments, accumulated))
                    tasks.append(("eval", argument))

            elif kind == "function_value":
                name, arguments, accumulated = task[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if name == "SUM":
                        accumulated += value
                    elif accumulated is None:
                        accumulated = value
                    elif name == "MIN":
                        accumulated = min(accumulated, value)
                    else:
                        accumulated = max(accumulated, value)
                    tasks.append(("function_next", name, arguments, accumulated))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
